/**
 * Adds 9 new materials to materials_rows.csv
 * Class 4 (Soft, Brittle Non-metals): Gallium Arsenide, MLCC, PZT Piezoelectric, Nickel-Zinc Ferrite, Aluminum Nitride Substrate
 * Class 5 (Medium-Hard Steels): Maraging Steel C250, Maraging Steel C300, API 5L X70, Hadfield Manganese Steel
 */
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const CSV_PATH = path.join(__dirname, '..', 'materials_rows.csv');

function uuid() {
  return crypto.randomUUID();
}

// Escape a CSV field: wrap in quotes if it contains commas, quotes, or newlines
function csvField(val) {
  if (val === null || val === undefined) return '';
  const s = String(val);
  if (s.includes(',') || s.includes('"') || s.includes('\n') || s.includes('\r')) {
    return '"' + s.replace(/"/g, '""') + '"';
  }
  return s;
}

function csvRow(obj, headers) {
  return headers.map(h => csvField(obj[h] || '')).join(',');
}

// Read existing CSV to get headers
const csvContent = fs.readFileSync(CSV_PATH, 'utf8');
const firstLine = csvContent.split('\n')[0];
// Parse headers properly
const headers = [];
let inQuote = false;
let field = '';
for (const ch of firstLine) {
  if (ch === '"') { inQuote = !inQuote; }
  else if (ch === ',' && !inQuote) { headers.push(field.trim()); field = ''; }
  else { field += ch; }
}
headers.push(field.trim());

console.log(`Found ${headers.length} headers`);

